def get_divisors(n):
    """Get all divisors of n"""
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return divisors

def min_prime_factor(n):
    """Get the smallest prime factor of n"""
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

def count_prime_factors(n):
    """Count total prime factors (with multiplicity)"""
    count = 0
    temp = n
    while temp % 2 == 0:
        count += 1
        temp //= 2
    i = 3
    while i * i <= temp:
        while temp % i == 0:
            count += 1
            temp //= i
        i += 2
    if temp > 1:
        count += 1
    return count

