    # Find all primes used in the array
    def get_prime_factors(x):
        factors = defaultdict(int)
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors[d] += 1
                x //= d
            d += 1
        if x > 1:
            factors[x] += 1
        return factors

    all_primes = set()
    for i in range(n):
        all_primes.update(get_prime_factors(a[i]).keys())

    total_ops = 0

    for prime in all_primes:
        # For each prime, count occurrences in each position
        counts = [0] * n
        for i in range(n):
            x = a[i]
            while x % prime == 0:
                counts[i] += 1
                x //= prime

        # Maximum flow: source -> odd positions -> even positions -> sink
        # Use Dinic's algorithm for max flow

        class Dinic:
            def __init__(self, n):
                self.n = n
                self.graph = [[] for _ in range(n)]

            def add_edge(self, u, v, cap):
                self.graph[u].append([v, cap, len(self.graph[v])])
                self.graph[v].append([u, 0, len(self.graph[u]) - 1])

            def bfs(self, s, t):
                self.level = [-1] * self.n
                self.level[s] = 0
                queue = [s]
                while queue:
                    u = queue.pop(0)
                    for v, cap, rev in self.graph[u]:
                        if cap > 0 and self.level[v] < 0:
                            self.level[v] = self.level[u] + 1
                            queue.append(v)
                return self.level[t] >= 0

            def dfs(self, u, t, flow, ptr):
                if u == t or flow == 0:
                    return flow
                for i in range(ptr[u], len(self.graph[u])):
                    ptr[u] = i
                    v, cap, rev = self.graph[u][i]
                    if self.level[v] == self.level[u] + 1 and cap > 0:
                        pushed = self.dfs(v, t, min(flow, cap), ptr)
                        if pushed > 0:
                            self.graph[u][i][1] -= pushed
                            self.graph[v][rev][1] += pushed
                            return pushed
                return 0

            def max_flow(self, s, t):
                total = 0
                while self.bfs(s, t):
                    ptr = [0] * self.n
                    while True:
                        pushed = self.dfs(s, t, float('inf'), ptr)
                        if pushed == 0:
                            break
                        total += pushed
                return total

        # Build flow network
        S = n, T = n + 1
        dinic = Dinic(n + 2)

        # Source to odd positions with capacity = count of prime
        for i in range(n):
            if (i + 1) % 2 == 1:  # odd index (1-indexed)
                if counts[i] > 0:
                    dinic.add_edge(S, i, counts[i])

        # Even positions to sink with capacity = count of prime
        for i in range(n):
            if (i + 1) % 2 == 0:  # even index (1-indexed)
                if counts[i] > 0:
                    dinic.add_edge(i, T, counts[i])

        # Good pairs between odd and even - infinite capacity
        for u, v in pairs:
            for i in range(n):
                for j in range(i + 1, n):
                    if ((i + 1) % 2 != (j + 1) % 2) and (i, j) in pairs:
                        pass

        # Better: directly add edges between connected good pairs
        for i in range(len(pairs)):
            u, v = pairs[i]
            # One is odd, one is even (1-indexed)
            if ((u + 1) % 2 == 1) and ((v + 1) % 2 == 0):
                dinic.add_edge(u, v, float('inf'))
            elif ((u + 1) % 2 == 0) and ((v + 1) % 2 == 1):
                dinic.add_edge(v, u, float('inf'))

        total_ops += dinic.max_flow(S, T)

    return f"{total_ops}\n"

