def sphere_from_4(p1, p2, p3, p4):
    # Circumsphere of tetrahedron - center is equidistant from all 4 points
    # Solve linear system
    matrix = []
    b = []

    for i, pi in enumerate([p1, p2, p3, p4]):
        matrix.append([2*(p1[0]-pi[0]), 2*(p1[1]-pi[1]), 2*(p1[2]-pi[2])])
        if i == 0:
