        elif i == 1:
            b.append(distSq(p1, pi))
        else:
            b.append(distSq(p1, pi))

    # Solve 3x3 system using Cramer's rule or direct inversion
    # Actually, simpler: use Gaussian elimination

    def solve():
        a = [[matrix[i][j] for j in range(3)] for i in range(3)]
        c = b[:3]

        for i in range(3):
            for j in range(i, 4):
                if abs(a[j][i]) < abs(a[i][i]):
                    a[i], a[j] = a[j], a[i]
                    c[i], c[j] = c[j], c[i]
                for k in range(i+1, 3):
                    factor = a[j][i] / a[i][j] if a[i][j] != 0 else 0
                    for col in range(i, 4):
                        a[j][col] -= factor * a[i][col]
                        if col < 4:
                            a[j][col] -= factor * a[i][col]
                    c[j] -= factor * c[j]

        det = a[0][0] * (a[1][1]*a[2][2] - a[1][2]*a[2][1]) - \
             a[0][1] * (a[1][0]*a[2][2] - a[1][2]*a[2][0]) + \
             a[0][2] * (a[1][0]*a[2][1] - a[1][1]*a[2][0])

        if abs(det) < 1e-9:
            return None

        x = (c[0]*(a[1][1]*a[2][2]-a[1][2]*a[2][1]) - 
             a[0][1]*(c[1]*a[2][2]-a[1][2]*c[2]) + 
             a[0][2]*(a[1][1]*c[2]-c[1]*a[2][1])) / det
        y = (a[0][0]*(c[1]*a[2][2]-a[1][2]*c[2]) - 
             c[0]*(a[1][0]*a[2][2]-a[1][2]*a[2][0]) + 
             a[0][2]*(a[1][0]*c[2]-c[1]*a[2][0])) / det
        z = (a[0][0]*(a[1][1]*c[2]-c[1]*a[2][1]) - 
             a[0][1]*(a[1][0]*c[2]-c[1]*a[2][0]) + 
             c[0]*(a[1][0]*a[2][1]-a[1][1]*a[2][0])) / det

        return [x, y, z]

