def point_from_tetra(p1, p2, p3, p4):
    """Find circumcenter of 4 points (sphere center equidistant to all 4)"""
    center = [(p1[0]+p2[0]+p3[0]+p4[0])/4.0, (p1[1]+p2[1]+p3[1]+p4[1])/4.0, (p1[2]+p2[2]+p3[2]+p4[2])/4.0]
    r = max(dist(p1, center), dist(p2, center), dist(p3, center), dist(p4, center))
