def find_min_enclosing_sphere(points):
    """Find the minimal enclosing sphere for a set of points"""
    if not points:
        return {'center': [0, 0, 0], 'radius': 0}

    n = len(points)
    if n == 1:
        return {'center': list(points[0]), 'radius': 0.0}

    # Use Welzl-like approach with pivot
