            if d > max_d:
                max_d = d

        if max_d <= sphere['radius'] + 1e-6:
            if max_d < best_r:
                best_r = max_d
                best_center = sphere['center']

        # Try 3-point spheres
        for i in range(n):
            sphere3 = sphere_from_3(start_p, furthest, points[i])
            if sphere3['radius'] < float('inf'):
                max_d = 0
                for j in range(n):
                    d = dist(points[j], sphere3['center'])
                    if d > max_d:
                        max_d = d
                if max_d <= sphere3['radius'] + 1e-6 and max_d < best_r:
                    best_r = max_d
                    best_center = sphere3['center']

        # Try 4-point spheres
        for i in range(n):
            for j in range(i+1, n):
                sphere4 = sphere_from_4(start_p, furthest, points[i], points[j])
                if sphere4['radius'] < float('inf'):
                    max_d = 0
                    for k in range(n):
