    if m == n - 1:
        return ''

    # Build MST
    sorted_edges = sorted(enumerate(edges), key=lambda x: x[1][2])
    uf = UnionFind(n)
    in_mset = set()

    for ix, (u, v, w, orig_idx) in sorted_edges:
        if uf.union(u, v):
            in_mset.add(orig_idx)

    # Build MST adjacency
    mst_adj = defaultdict(list)
    for ix, (u, v, w, orig_idx) in sorted_edges:
        if orig_idx in in_mset:
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))

    # LCA with path max
    dep = [0] * (n + 1)
    up = [[0] * 18 for _ in range(n + 1)]
    mx = [[0] * 18 for _ in range(n + 1)]

    q = deque([1])
    visited = [False] * (n + 1)
    visited[1] = True

    while q:
        u = q.popleft()
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                dep[v] = dep[u] + 1
                up[v][0] = u
                mx[v][0] = w
                q.append(v)

    # Build binary lifting
    for j in range(1, 18):
        for i in range(1, n + 1):
            up[i][j] = up[up[i][j-1]][j-1] if up[i][j-1] else 0
            mx[i][j] = max(mx[i][j-1], mx[up[i][j-1]][j-1]) if up[i][j-1] else mx[i][j-1]

    def query(u, v):
        if dep[u] < dep[v]:
            u, v = v, u

        res = 0
        diff = dep[u] - dep[v]
        for j in range(18):
            if diff & (1 << j):
                res = max(res, mx[u][j])
                u = up[u][j]

        if u == v:
            return res

        for j in range(17, -1, -1):
            if up[u][j] != up[v][j]:
                res = max(res, mx[u][j], mx[v][j])
                u = up[u][j]
                v = up[v][j]

        return max(res, mx[u][0], mx[v][0])

    output = []
    for u, v, w, orig_idx in edges:
        if orig_idx not in in_mset:
            output.append(str(query(u, v)))

