    if n == 3:
        return str(f3 % MOD)

    # Matrix exponentiation for recurrence a_n = a_{n-1} + a_{n-2} + a_{n-3}

    def mat_mul(A, B):
        C = [[0]*3 for _ in range(3)]
        for i in range(3):
            for k in range(3):
                for j in range(3):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        result = [[0]*3 for _ in range(3)]
        for i in range(3): result[i][i] = 1
        while p:
            if p & 1: result = mat_mul(result, A)
            A = mat_mul(A, A)
            p >>= 1
        return result

    # T for [a_n, a_{n-1}, a_{n-2}] -> [a_{n+1}, a_n, a_{n-1}]
    T = [[1, 1, 1], [1, 0, 0], [0, 1, 0]]
    T3 = mat_pow(T, n - 3)

    # Initial for f_4: [1, 1, 1] (f3^1 * f2^1 * f1^1)\n
    f3_p = sum((T3[0][i] * [1, 1, 1][i]) for i in range(3)) % MOD\n
    f2_p = sum((T3[1][i] * [1, 1, 1][i]) for i in range(3)) % MOD\n
    f1_p = sum((T3[2][i] * [1, 1, 1][i]) for i in range(3)) % MOD\n\n
    # c exponent = n^2 - 5n + 6\n
    c_exp = (n * n - 5 * n + 6) % (MOD - 1)\n\n
    result = pow(c, c_exp, MOD)\n
    result = (result * pow(f1, f1_p, MOD)) % MOD\n
    result = (result * pow(f2, f2_p, MOD)) % MOD\n
    result = (result * pow(f3, f3_p, MOD)) % MOD\n\n
    return str(result)\n

