def count_in_range(start, end):
    """Count total digits in numbers from start to end (inclusive)"""
    if start > end:
        return 0

    count = 0

    for length in range(1, 19):
        start_len = 10**(length - 1) if length > 1 else 1
        end_len = 10**length - 1

        start_bound = max(start_len, start)
        end_bound = min(end_len, end)

        if start_bound <= end_bound:
            count += (end_bound - start_bound + 1) * length

    return count

def block_length(n):
    """Calculate total digits in block n (sequence "123...n")"""
    if n <= 0:
        return 0

    return count_in_range(1, n)

def find_digit(k):
    """Find the k-th digit in the infinite sequence"""
    if k <= 0:
        raise ValueError("k must be positive")

    pos = k
    n = 1

    # Find which block contains the k-th digit
