                # Cyclic shift columns left: new[j] = old[(j+1)%n]
                for i in range(n):
                    matrix[i] = [matrix[i][(j + 1) % n] for j in range(n)]
            elif op == 'D':
                # Cyclic shift rows down: row 0 becomes row 1, ..., row n-1 becomes row 0
                temp = [row[:] for row in matrix]
                matrix = [temp[-1]] + temp[:-1]
            elif op == 'U':
                # Cyclic shift rows up: row 0 moves to end
                temp = [row[:] for row in matrix]
                matrix = temp[1:] + [temp[0]]
            elif op == 'I':
                # Inverse each row permutation
                for i in range(n):
                    row = matrix[i]
                    inv_row = [0] * n
                    for j, val in enumerate(row):
                        inv_row[val - 1] = j + 1
                    matrix[i] = inv_row
            elif op == 'C':
                # Inverse each column permutation
                # Transpose to work on columns as rows
                transposed = [[matrix[j][i] for j in range(n)] for i in range(n)]
                for i in range(n):
                    row = transposed[i]
                    inv_row = [0] * n
                    for j, val in enumerate(row):
                        inv_row[val - 1] = j + 1
                    transposed[i] = inv_row
                # Transpose back
