def solution(s):
    MOD = 998244353

    n, k = map(int, s.strip().split())

    # Edge cases
    if k > n:
        return "0\n"
    if k == 1:
        return f"{n}\n"

    # Precompute factorials and inverse factorials for C(n, r)
    limit = n + 1
    fact = [1] * limit
    for i in range(1, limit):
        fact[i] = (fact[i-1] * i) % MOD

    def modInverse(x):
        return pow(x, MOD - 2, MOD)

    invFact = [1] * limit
    invFact[-1] = modInverse(fact[-1])
    for i in range(limit - 2, -1, -1):
        invFact[i] = (invFact[i+1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * invFact[r] % MOD * invFact[n-r] % MOD

    ans = 0
    for a1 in range(1, n + 1):
        m = n // a1  # Number of multiples of a1 in [1, n]
        if m >= k:
            # Choose k-1 additional elements from m-1 remaining multiples
            ans = (ans + nCr(m - 1, k - 1)) % MOD

    return f"{ans}\n"

