def is_valid(s, strings):
    """Check if s is a valid good string for the given set of strings."""
    if not s:
        return False

    # Count occurrences of each required string
    required_counts = {}
    for string in strings:
        if string not in s:
            return False
        # Count non-overlapping or overlapping occurrences if needed
        cnt = 0
        i = 0
        while True:
            idx = s.find(string, i)
            if idx == -1:
                break
            cnt += 1
            i = idx + 1
        required_counts[string] = cnt

    if not required_counts:
        return False

    min_cnt = min(required_counts.values())

    # All required strings must appear at least min_cnt times
    # Also check that no other substring exceeds min_cnt
    check_string = s
    all_substrings = set()

    # Sample some substrings for efficiency
    for i in range(min(100, len(check_string))):
        for j in range(i + 1, min(i + 100, len(check_string))):
            sub = check_string[i:j]
            if sub in required_counts:
                continue
            all_substrings.add(sub)

    for sub in all_substrings:
        if len(sub) < 2:
            continue
        cnt = 0
        i = 0
        while True:
            idx = check_string.find(sub, i)
            if idx == -1:
                break
            cnt += 1
            i = idx + 1
        if cnt > min_cnt:
            return False

    return True


