            # Build the "reconstructed" tree where missing_vertex is added as child of candidate_parent
            reconstructed = defaultdict(list)

            for u in list(graph.keys()):
                if u == missing_vertex or candidate_parent == u:
                    continue
                for v in graph[u]:
                    if v != missing_vertex:
