            # Add the reconstruction: missing_vertex becomes child of candidate_parent
            reconstructed[missing_vertex] = [candidate_parent]
            reconstructed[candidate_parent].append(missing_vertex)

            # Verify it's a complete binary tree with n levels
            if len(reconstructed) != total_original:
