            # BFS to check tree structure
            visited = set()
            correct_depths = True
            leaf_depths = []

            q = deque([1])
            root_seen = False

            while q:
                node = q.popleft()
                if node not in visited:
                    visited.add(node)

                    if node not in reconstructed or len(reconstructed[node]) != 2:
                        # Root might have 1 child
                        if not root_seen:
                            root_seen = True
                            continue
                        correct_depths = False
                        break

                    for child in reconstructed[node]:
                        if child not in visited:
                            q.append(child)

            # Check all depths
            if correct_depths:
                from collections import deque
                depth_map = {}

                if root_seen:
                    q = deque([1])
                    while q:
                        node = q.popleft()
                        d = depth_map.get(node, 0)
                        if node in reconstructed:
                            for child in reconstructed[node]:
                                depth_map[child] = d + 1
                                q.append(child)

                # All leaves should be at depth n-1
                for v in range(1, total_original + 1):
