        # More straightforward approach: check if tree matches expected structure
        valid_parents = []
        candidates_checked = 0

        # Key insight: try each vertex as potential parent, verify structure
        def verify_tree(parent_node):
            nonlocal valid_parents

            # Build adjacency without the removed node
            adj = defaultdict(list)
            for u in vertices_present:
                for v in graph[u]:
                    adj[u].append(v)

            # Add link from parent to missing node (as if it existed)
            adj[parent_node].append(missing_vertex)
            adj[missing_vertex].append(parent_node)

            # Check perfect binary tree structure
            if len(adj) != total_original:
                return False

            # Check all nodes have correct degree pattern
            for v in range(1, total_original + 1):
                if v not in adj:
                    return False

            return True

        # Determine valid parents by hand
        for p in range(1, total_output + 1):
            if p == missing_vertex:
                continue

            # Check if p is a valid parent (not leaf, has enough capacity)
            degree = 0
            if p in vertices_present:
                degree = len(graph.get(p, []))

            # Root can be parent, but nodes at depth <= n-2 should be able to have child
            if degree >= 0 and verify_tree(p):
                valid_parents.append(p)

        valid_parents = sorted(list(set(valid_parents)))
        cnt = len(valid_parents)

